import { test, expect } from '@playwright/test';

test.describe('Filter List by Multiple Statuses', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/list');
  });

  test('should filter list by multiple statuses simultaneously', async ({ page }) => {
    // Verify initial list is displayed
    const listItems = page.locator('[data-testid="list-item"]');
    await expect(listItems).toHaveCount(10);

    // Verify all items are visible
    const allItems = page.locator('[data-testid="list-item"]');
    await expect(allItems).toBeVisible();

    // Click filter button
    const filterButton = page.getByRole('button', { name: /filter by status/i });
    await filterButton.click();

    // Verify filter dropdown appears
    const filterDropdown = page.locator('[data-testid="filter-dropdown"]');
    await expect(filterDropdown).toBeVisible();

    // Select multiple statuses using checkboxes
    const statuses = page.locator('[data-testid="status-filter-checkbox"]');
    await statuses.first().click();
    await statuses.nth(1).click();
    await statuses.nth(2).click();

    // Verify filter is applied
    const filteredItems = page.locator('[data-testid="list-item"][data-filter="active,completed,archived"]');
    await expect(filteredItems).toHaveCount(3);

    // Verify filtered items are visible
    await expect(filteredItems).toBeVisible();

    // Verify no items are hidden
    const hiddenItems = page.locator('[data-testid="list-item"][data-filter="pending"]');
    await expect(hiddenItems).not.toBeVisible();

    // Verify filter button is disabled after selection
    await expect(filterButton).toBeDisabled();
  });

  test('should handle clearing all filters and reset list', async ({ page }) => {
    // Verify initial list is displayed
    const listItems = page.locator('[data-testid="list-item"]');
    await expect(listItems).toHaveCount(10);

    // Click filter button
    const filterButton = page.getByRole('button', { name: /filter by status/i });
    await filterButton.click();

    // Verify filter dropdown appears
    const filterDropdown = page.locator('[data-testid="filter-dropdown"]');
    await expect(filterDropdown).toBeVisible();

    // Select multiple statuses using checkboxes
    const statuses = page.locator('[data-testid="status-filter-checkbox"]');
    await statuses.first().click();
    await statuses.nth(1).click();
    await statuses.nth(2).click();

    // Verify filter is applied
    const filteredItems = page.locator('[data-testid="list-item"][data-filter="active,completed,archived"]');
    await expect(filteredItems).toHaveCount(3);

    // Verify list is filtered
    await expect(filteredItems).toBeVisible();

    // Verify clear button is visible
    const clearButton = page.getByRole('button', { name: /clear filters/i });
    await expect(clearButton).toBeVisible();

    // Click clear button
    await clearButton.click();

    // Verify list is reset to all items
    const allItems = page.locator('[data-testid="list-item"]');
    await expect(allItems).toHaveCount(10);

    // Verify filter dropdown is closed
    const filterDropdown = page.locator('[data-testid="filter-dropdown"]');
    await expect(filterDropdown).not.toBeVisible();

    // Verify filter button is enabled
    await expect(filterButton).not.toBeDisabled();
  });
});
